import java.util.List;

public class Solution {
    public static List<List<Integer>> combinationSum2(int[] candidates, int target) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> combination = new ArrayList<>();
        Arrays.sort(candidates);
        combine(Arrays.stream(candidates).boxed().collect(Collectors.toList()), target, result, combination, 0);
        return result;
    }

    private static void combine(List<Integer> candidates, int target, List<List<Integer>> result, List<Integer> combination, int index) {
        if (target == 0) {
            result.add(new ArrayList<>(combination));
            return;
