        for (int i = index; i < candidates.size() && target >= candidates.get(i); ++i) {
            if (i == index || !candidates.get(i).equals(candidates.get(i - 1))) {
                combination.add(candidates.get(i));
                combine(candidates.subList(i + 1, candidates.size()), target - candidates.get(i), result, combination, i + 1);
                combination.remove(combination.size() - 1);
            }
        }
    }

