    std::unordered_map<char, int> in_degree;

    // Initialize in-degree for each character
    for (const auto& word : words) {
        for (char c : word) {
            in_degree[c] = 0;
        }
    }

    // Build the graph and update in-degrees
    for (size_t i = 0; i < words.size() - 1; ++i) {
        const auto& word1 = words[i];
        const auto& word2 = words[i + 1];

        bool found = false;
        for (size_t j = 0; j < std::min(word1.length(), word2.length()); ++j) {
            if (word1[j] != word2[j]) {
                if (graph[word1[j]].find(word2[j]) == graph[word1[j]].end()) {
                    graph[word1[j]].insert(word2[j]);
                    in_degree[word2[j]]++;
                }
                found = true;
                break;
            }
        }

        // If no common prefix and word1 is longer than word2, return empty string
        if (!found && word1.length() > word2.length()) {
            return "";
        }
    }

    // Topological sorting using Kahn's algorithm
    std::queue<char> q;
    for (const auto& pair : in_degree) {
        if (pair.second == 0) {
            q.push(pair.first);
        }
    }

    std::string result;
    while (!q.empty()) {
        char c = q.front();
        q.pop();
        result += c;

        for (char neigh : graph[c]) {
