public class Solution {
    public int[] countSmaller(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Integer[] indices = new Integer[n];

        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }

        mergeSort(indices, nums, result, 0, n - 1);

        return result;
    }

    private void mergeSort(Integer[] indices, int[] nums, int[] result, int left, int right) {
        if (left >= right) {
            return;
        }

        int mid = (left + right) / 2;
        mergeSort(indices, nums, result, left, mid);
        mergeSort(indices, nums, result, mid + 1, right);

        merge(indices, nums, result, left, mid, right);
    }

    private void merge(Integer[] indices, int[] nums, int[] result, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        Integer[] leftArray = new Integer[n1];
        Integer[] rightArray = new Integer[n2];

        for (int i = 0; i < n1; i++) {
            leftArray[i] = indices[left + i];
        }

        for (int j = 0; j < n2; j++) {
            rightArray[j] = indices[mid + 1 + j];
        }

        int i = 0, j = 0, k = left;

        while (i < n1 && j < n2) {
            if (nums[leftArray[i]] <= nums[rightArray[j]]) {
                result[leftArray[i]] += j;
                indices[k++] = leftArray[i++];
            } else {
                indices[k++] = rightArray[j++];
