public class Solution {
    private static final int[][] DIRS = {{0, 0, 1, -1}, {1, -1, 0, 0}};

    public int longestIncreasingPath(int[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return 0;
        }

        int m = matrix.length;
        int n = matrix[0].length;
        int[][] memo = new int[m][n];

        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                ans = Math.max(ans, dfs(matrix, memo, i, j));
            }
        }

        return ans;
    }

    private int dfs(int[][] matrix, int[][] memo, int i, int j) {
        if (memo[i][j] != 0) {
            return memo[i][j];
        }

        int maxLen = 0;
        for (int[] dir : DIRS) {
            int ni = i + dir[0];
            int nj = j + dir[1];
            if (isValid(matrix, ni, nj) && matrix[ni][nj] > matrix[i][j]) {
                maxLen = Math.max(maxLen, dfs(matrix, memo, ni, nj));
            }
        }

        memo[i][j] = maxLen + 1;
        return memo[i][j];
    }

    private boolean isValid(int[][] matrix, int i, int j) {
        return i >= 0 && i < matrix.length && j >= 0 && j < matrix[0].length;
