int trapRainWater(std::vector<std::vector<int>>& heightMap) {
    int m = heightMap.size();
    int n = heightMap[0].size();
    std::priority_queue<std::pair<int, std::pair<int, int>>, std::vector<std::pair<int, std::pair<int, int>>>, std::greater<std::pair<int, std::pair<int, int>>>> pq;
    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n));

    // Add all boundary cells to the priority queue
    for (int i = 0; i < m; ++i) {
        pq.push({heightMap[i][0], {i, 0}});
        pq.push({heightMap[i][n - 1], {i, n - 1}});
        visited[i][0] = true;
        visited[i][n - 1] = true;
    }
    for (int j = 1; j < n - 1; ++j) {
        pq.push({heightMap[0][j], {0, j}});
        pq.push({heightMap[m - 1][j], {m - 1, j}});
        visited[0][j] = true;
        visited[m - 1][j] = true;
    }

    int water = 0;
    int maxHeight = 0;
    std::vector<std::pair<int, int>> dirs{{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    while (!pq.empty()) {
        auto [h, pos] = pq.top();
        pq.pop();
        maxHeight = std::max(maxHeight, h);
        int r = pos.first;
        int c = pos.second;

        for (auto [dr, dc] : dirs) {
            int x = r + dr;
            int y = c + dc;
            if (x < 0 || x >= m || y < 0 || y >= n || visited[x][y]) {
                continue;
            }
            if (heightMap[x][y] < maxHeight) {
                water += maxHeight - heightMap[x][y];
            }
            pq.push({heightMap[x][y], {x, y}});
            visited[x][y] = true;
        }
    }

    return water;
}

int main() {
    std::vector<std::vector<int>> heightMap = {{1, 4, 3, 1, 3, 2},
                                               {3, 2, 1, 3, 2, 4},
                                               {2, 3, 3, 2, 3, 1}};
    std::cout << trapRainWater(heightMap) << std::endl; // Output: 4
    return 0;
}
