        // Create a priority queue to store projects based on their capital requirement
        PriorityQueue<int[]> projectPool = new PriorityQueue<>(Comparator.comparingInt(o -> o[0]));
        for (int i = 0; i < profits.length; i++) {
            projectPool.add(new int[]{capital[i], profits[i]});
