public class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][][] dp = new int[n][n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    dp[i][j][k] = 0;
                }
            }
        }

        for (int len = 1; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                for (int k = 0; k <= j; k++) {
                    if (i == j) {
                        dp[i][j][k] = (k + 1) * (k + 1);
                    } else {
                        while (j > i && boxes[j] == boxes[j - 1]) {
                            j--;
                            k++;
                        }
                        dp[i][j][k] = (k + 1) * (k + 1) + dp[i][j - 1][0];

                        for (int m = i; m < j; m++) {
                            if (boxes[m] == boxes[j]) {
                                dp[i][j][k] = Math.max(dp[i][j][k], dp[i][m][k + 1] + dp[m + 1][j - 1][0]);
                            }
                        }
                    }
                }
            }
        }

        return dp[0][n - 1][0];
    }
}
