    public String splitLoopedString(String[] strs) {
        String ans = "";
        String cur = "";

        // Create a string with the longest possible rotation of each word
        for (String s : strs) {
            cur += Math.max(s, new StringBuilder(s).reverse().toString());
        }

        // Iterate over each word and its rotations
        for (int i = 0; i < strs.length; i++) {
            String s = strs[i];
            for (String xstr : new String[]{s, new StringBuilder(s).reverse().toString()}) {
                for (int j = 0; j < xstr.length(); j++) {
