int shoppingOffers(std::vector<int>& price, std::vector<std::vector<int>>& special, std::vector<int>& needs) {
    auto helper = [&](int index) {
        if (index == special.size()) {
            int cost = 0;
            for (int i = 0; i < needs.size(); ++i) {
                cost += needs[i] * price[i];
            }
            return cost;
        }

        int noOffer = helper(index + 1);
        bool canApplyOffer = true;
        for (int i = 0; i < needs.size(); ++i) {
            needs[i] -= special[index][i];
            if (needs[i] < 0) {
                canApplyOffer = false;
            }
        }

        int withOffer = INT_MAX;
        if (canApplyOffer) {
            int offerCost = special[index].back() + helper(index);
            withOffer = std::min(noOffer, offerCost);
        }

        for (int i = 0; i < needs.size(); ++i) {
            needs[i] += special[index][i];
        }

        return withOffer;
    };

    return helper(0);
}

int main() {
