std::vector<int> findRedundantDirectedConnection(std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(edges.size() + 1);
    std::vector<int> candidateA, candidateB;

    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];

        if (parent[v] > 0) {
            candidateA = {parent[v], v};
            candidateB = {u, v};
        } else {
            parent[v] = u;
        }
    }

    for (int i = 1; i <= edges.size(); ++i) {
        int cycle = i;
        int steps = edges.size();
        while (parent[cycle] != 0 && steps > 0) {
            cycle = parent[cycle];
            --steps;
        }
        if (steps == 0) {
            if (!candidateA.empty()) {
                return candidateA;
            } else {
                return {parent[i], i};
            }
        }
    }

    return candidateB;
}

