    right[n - k] = n - k;

    for (int i = 1; i < n - k + 1; ++i) {
        left[i] = sums[i] > sums[left[i - 1]] ? i : left[i - 1];
    }

    for (int i = n - k - 1; i >= 0; --i) {
        right[i] = sums[i] >= sums[right[i + 1]] ? i : right[i + 1];
    }

    int max_sum = 0;

