    int n = nums.size();
    int total_sum = accumulate(nums.begin(), nums.end(), 0);

    if (total_sum % n != 0) return false;

    int target_sum = total_sum * (n / 2) / n;
    vector<vector<bool>> dp(n / 2 + 1, vector<bool>(target_sum + 1, false));
