int largestComponentSize(std::vector<int>& nums) {
    std::unordered_map<int, int> primeMap;
    std::unordered_map<int, std::vector<int>> graph;

    // Find the prime factorization of each number
    for (int num : nums) {
        int prime = num;
        for (int i = 2; i * i <= num; ++i) {
            if (num % i == 0) {
                prime = i;
                break;
            }
        }
        primeMap[num] = prime;
        graph[prime].push_back(num);
        if (num != prime) {
            graph[num].push_back(prime);
        }
    }

    // Find the largest connected component
    int count = 0;
    for (int num : nums) {
        int prime = primeMap[num];
        int size = 1;
        std::unordered_set<int> visited;
        std::queue<int> q;
        q.push(prime);
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            if (visited.find(node) != visited.end()) {
                continue;
            }
            visited.insert(node);
            size++;
            for (int neighbor : graph[node]) {
                q.push(neighbor);
            }
        }
        count = std::max(count, size);
    }

    return count;
}

