import java.util.*;

public class Solution {
    public int numSquarefulPerms(int[] A) {
        Set<Integer> keySet = new HashSet<>();
        for (int num : A) {
            keySet.add(num);
        }
        Map<Integer, Integer> counter = new HashMap<>();
        for (int num : A) {
            counter.put(num, counter.getOrDefault(num, 0) + 1);
        }

        return dfs(0, A, keySet, counter);
    }

    private int dfs(int idx, int[] A, Set<Integer> keySet, Map<Integer, Integer> counter) {
        if (idx == A.length) {
            return 1;
        }

        int count = 0;
        for (int key : keySet) {
            if (counter.get(key) > 0 && (idx == 0 || isSquare(A[idx - 1], key))) {
                counter.put(key, counter.get(key) - 1);
                A[idx] = key;
                count += dfs(idx + 1, A, keySet, counter);
                counter.put(key, counter.get(key) + 1);
            }
        }

        return count;
    }

    private boolean isSquare(int a, int b) {
        return Math.sqrt(a + b) % 1 == 0;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] A = {1, 17, 8};
        System.out.println(solution.numSquarefulPerms(A)); // Output: 2
    }
}
