import collections

class Solution:
    def mostVisitedPattern(self, username: List[str], timestamp: List[int], website: List[str]) -> List[str]:
        # Create a dictionary to store the visiting order of each user
        user_visits = collections.defaultdict(list)
        for i in range(len(username)):
            user_visits[username[i]].append((timestamp[i], website[i]))

        # Sort the visiting order of each user
        for user in user_visits:
            user_visits[user].sort(key=lambda x: x[0])

        # Find all possible patterns of three websites visited by the same user
        patterns = set()
        for user in user_visits:
            n = len(user_visits[user])
            for i in range(n):
                for j in range(i+1, n):
                    for k in range(j+1, n):
                        pattern = tuple(user_visits[user][i][1], user_visits[user][j][1], user_visits[user][k][1])
                        patterns.add(pattern)

        # Count the frequency of each pattern
        pattern_count = collections.defaultdict(int)
        for pattern in patterns:
            pattern_count[pattern] += 1

        # Find the most visited pattern
        max_count = 0
        most_visited_pattern = None
        for pattern, count in pattern_count.items():
            if count > max_count:
                max_count = count
                most_visited_pattern = pattern

        return list(most_visited_pattern)
