int minHeightShelves(std::vector<std::pair<int, int>>& books, int shelf_width) {
    int n = books.size();
    std::vector<int> dp(n + 1, 1000000);
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        int width = 0;
        int height = 0;
        int j = i;
        while (j > 0 && width + books[j - 1].first <= shelf_width) {
            width += books[j - 1].first;
            height = std::max(height, books[j - 1].second);
            dp[i] = std::min(dp[i], dp[j - 1] + height);
            --j;
        }
    }

    return dp[n];
}
