        // Sort each group
        for (string& group : groups) {
            sort(group.begin(), group.end(), greater<char>());
        }

        // Build the result string
        string res;
        for (int i = 0; i < n; ++i) {
            char smallest_char = groups[find(i)].back(); 
            res += smallest_char;
            groups[find(i)].pop_back();
        }

