import java.util.Arrays;

public class JobScheduling {
    public static int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.length;
        int[][] jobs = new int[n][3];

        // Create a 2D array to store the start time, end time, and profit of each job
        for (int i = 0; i < n; i++) {
            jobs[i] = new int[]{startTime[i], endTime[i], profit[i]};
        }

        // Sort the jobs based on their end times
        Arrays.sort(jobs, (a, b) -> a[1] - b[1]);

        // Create an array to store the maximum profit that can be achieved up to each job
        int[] dp = new int[n];
        dp[0] = jobs[0][2];

        // Fill the dp array using dynamic programming
        for (int i = 1; i < n; i++) {
            int maxProfit = dp[i - 1];
            int j = i - 1;
            while (j >= 0 && jobs[j][1] > jobs[i][0]) {
                j--;
            }
            if (j != -1) {
                maxProfit = Math.max(maxProfit, dp[j] + jobs[i][2]);
            }
            dp[i] = maxProfit;
        }

        return dp[n - 1];
    }

