int stoneGameII(std::vector<int>& piles) {
    int n = piles.size();
    for (int i = n - 2; i >= 0; --i) {
        piles[i] += piles[i + 1];
    }

    std::vector<std::vector<int>> memo(n, std::vector<int>(n, -1));
    function<int(int, int)> search = [&](int idx, int M) {
        if (idx + 2 * M >= n) {
            return piles[idx];
        }
        if (memo[idx][M] != -1) {
            return memo[idx][M];
        }
        int ans = INT_MIN;
        for (int x = 1; x <= 2 * M; ++x) {
            ans = std::max(ans, piles[idx] - search(idx + x, std::max(M, x)));
        }
        return memo[idx][M] = ans;
    };

    return search(0, 1);
}

int main() {
