double frogPosition(int n, std::vector<std::vector<int>>& edges, int t, int target) {
    std::unordered_map<int, std::vector<int>> graph;
    for (const auto& edge : edges) {
        graph[edge[0]].push_back(edge[1]);
        graph[edge[1]].push_back(edge[0]);
    }

    std::vector<double> ans(1, 0.0);
    std::function<void(int, int, int, double)> dfs = [&](int node, int parent, int t, double prob) {
        if (t == 0) {
            if (node == target) {
                ans[0] += prob;
            }
            return;
        }

        bool has_child = false;
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                has_child = true;
                dfs(neighbor, node, t - 1, prob / (graph[node].size() - (node == 1 ? 0 : 1)));
            }
        }

        if (!has_child && node == target) {
            ans[0] += prob;
        }
