import java.util.*;

public class Solution {
    public String reformat(String s) {
        Queue<Character> letters = new LinkedList<>();
        Queue<Character> digits = new LinkedList<>();

        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) {
                letters.add(c);
            } else {
                digits.add(c);
            }
        }

        if (Math.abs(letters.size() - digits.size()) > 1) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        boolean useLetter = letters.size() > digits.size();

        while (!letters.isEmpty() || !digits.isEmpty()) {
            if (useLetter) {
                result.append(letters.poll());
            } else {
                result.append(digits.poll());
            }
            useLetter = !useLetter;
        }

        return result.toString();
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        String input = "a0b1c2";
        String output = solution.reformat(input);
        System.out.println(output); // Expected output: "0a1b2c"
    }
}
