import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static double getProbability(int[] balls) {
        int sumBalls = 0;
        for (int ball : balls) {
            sumBalls += ball;
        }

        long totalCombinations = 1;
        for (int ball : balls) {
            totalCombinations *= factorial(ball);
        }

        List<Integer> combinations = new ArrayList<>();
        return dfs(balls, combinations, 0) / (double) totalCombinations;
    }

    private static long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    private static long dfs(int[] balls, List<Integer> combinations, int currBall) {
        if (currBall == balls.length) {
            if (combinations.get(0) == combinations.get(balls.length - 1)) {
                return countCombinations(balls, combinations);
            } else {
                return 0;
            }
        }

        long result = 0;
        for (int i = 0; i <= balls[currBall]; i++) {
            combinations.add(i);
            result += dfs(balls, combinations, currBall + 1);
            combinations.remove(combinations.size() - 1);
        }

        return result;
    }

    private static long countCombinations(int[] balls, List<Integer> combinations) {
        long totalCombinations = 1;
        for (int i = 0; i < balls.length; i++) {
            totalCombinations *= factorial(balls[i] + combinations.get(i)) / (factorial(balls[i]) * factorial(combinations.get(i)));
        }

        return totalCombinations;
    }

    public static void main(String[] args) {
        int[] balls = {1, 1};
        System.out.println(getProbability(balls)); // Output: 1.00000
    }
}
