public class Solution {
    public int[] BSTSequences(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            result.add(new ArrayList<>());
            return result.get(0).stream().mapToInt(i -> i).toArray();
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<TreeNode> levelNodes = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                levelNodes.add(node);
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            List<List<Integer>> subResults = new ArrayList<>();
            for (List<Integer> subResult : result) {
                for (TreeNode node : levelNodes) {
                    List<Integer> newResult = new ArrayList<>(subResult);
                    newResult.add(node.val);
                    subResults.add(newResult);
                }
            }
            result = subResults;
        }

        int[][] output = new int[result.size()][];
        for (int i = 0; i < result.size(); i++) {
            output[i] = result.get(i).stream().mapToInt(j -> j).toArray();
        }
        return output;
    }
}
