public class Solution {
    public int minSubarray(int[] nums, int p) {
        int n = nums.length;
        int res = n;
        int need = 0;
        for (int num : nums) {
            need = (need + num) % p;
        }
        if (need == 0) {
            return 0;
        }
        Map<Integer, Integer> lastSeen = new HashMap<>();
        lastSeen.put(0, -1);
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur = (cur + nums[i]) % p;
            lastSeen.putIfAbsent(cur, i);
            res = Math.min(res, i - lastSeen.get((cur - need + p) % p));
        }
        return res < n ? res : -1;
    }
}
