    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];

        // Calculate the length of the longest increasing subsequence ending at each index
        for (int i = 1; i < n; ++i) {
