int maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
    // Create a Trie data structure
    struct TrieNode {
        TrieNode* children[2];
    };

    TrieNode* root = new TrieNode();

    // Insert all numbers into the Trie
    for (int num : nums) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (!node->children[bit]) {
                node->children[bit] = new TrieNode();
            }
            node = node->children[bit];
        }
    }

    // Process each query
    vector<int> ans(queries.size());
    for (int i = 0; i < queries.size(); i++) {
        int x = queries[i][0];
        int m = queries[i][1];
        int idx = queries[i][2];

        // Find the maximum possible value of x ^ y where y <= m
        TrieNode* node = root;
        for (int j = 31; j >= 0; j--) {
            int bit = (x >> j) & 1;
            if (node->children[1 ^ bit]) {
                node = node->children[1 ^ bit];
                ans[idx] |= 1 << j;
            } else {
                node = node->children[bit];
            }
        }

        // If no valid y is found, set the answer to -1
        if (!node) {
            ans[idx] = -1;
        }
    }

    return ans;
}

