struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    ListNode* reverseGroup(ListNode* head, int k) {
        if (!head || k == 1) {
            return head;
        }
        ListNode* prev = nullptr;
        ListNode* cur = head;
        for (int i = 0; i < k; ++i) {
            ListNode* next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        head->next = cur;
        return prev;
    }

    ListNode* reverseEvenGroups(ListNode* head) {
        ListNode* dummy = new ListNode(0);
        dummy->next = head;
        ListNode* prev = dummy;
        int n = 0;
        ListNode* cur = head;
        while (cur) {
            ++n;
            cur = cur->next;
        }
        int i = 1, k = 1;
        while (n >= 0 && k <= n) {
            if (i % 2 == 0) {
                ListNode* tail = prev->next;
                ListNode* next = prev->next;
                for (int j = 0; j < k; ++j) {
                    next = next->next;
                }
                prev->next = reverseGroup(tail, k);
                tail->next = next;
            }
            n -= k;
            for (int j = 0; j < k; ++j) {
                prev = prev->next;
            }
            i += 1;
            k += i;
        }
        return dummy->next;
    }
};

int main() {
    // Create the linked list: 5 -> 2 -> 6 -> 3 -> 9 -> 1 -> 7 -> 3 -> 8 -> 4
    ListNode* head = new ListNode(5);
    head->next = new ListNode(2);
    head->next->next = new ListNode(6);
    head->next->next->next = new ListNode(3);
    head->next->next->next->next = new ListNode(9);
    head->next->next->next->next->next = new ListNode(1);
    head->next->next->next->next->next->next = new ListNode(7);
    head->next->next->next->next->next->next->next = new ListNode(3);
    head->next->next->next->next->next->next->next->next = new ListNode(8);
    head->next->next->next->next->next->next->next->next->next = new ListNode(4);

    Solution solution;
    ListNode* result = solution.reverseEvenGroups(head);

    // Print the resulting linked list
    while (result) {
        std::cout << result->val << " ";
        result = result->next;
    }
    std::cout << std::endl;

    // Clean up memory
    while (head) {
        ListNode* temp = head;
        head = head->next;
        delete temp;
    }

    return 0;
}
