public class LargestEvenSum {
    public static int largestEvenSum(int[] nums, int k) {
        // Separate even and odd numbers
        List<Integer> evens = new ArrayList<>();
        List<Integer> odds = new ArrayList<>();
        for (int num : nums) {
            if (num % 2 == 0) {
                evens.add(num);
            } else {
                odds.add(num);
            }
        }

        // Sort even numbers in descending order
        Collections.sort(evens, Collections.reverseOrder());

        // Sort odd numbers in descending order
        Collections.sort(odds, Collections.reverseOrder());

        int sum = 0;
        // Add k largest even numbers
        for (int i = 0; i < k; i++) {
            if (!evens.isEmpty()) {
                sum += evens.remove(evens.size() - 1);
            }
        }

        // Add k-1 largest odd numbers in pairs
        for (int i = 0; i < k - 1; i += 2) {
            if (!odds.isEmpty()) {
                int first = odds.remove(odds.size() - 1);
                if (!odds.isEmpty()) {
                    int second = odds.remove(odds.size() - 1);
                    sum += first + second;
                }
            }
        }

        // Return the largest even sum if possible
        return sum % 2 == 0 ? sum : -1;
    }

    public static void main(String[] args) {
        int[] nums = {4, 1, 5, 3, 1};
        int k = 3;
        System.out.println(largestEvenSum(nums, k)); // Output: 12
    }
}
