public class MaxNodesWithoutRestricted {
    public static int maxNodesWithoutRestricted(int n, int[][] edges, int[] restricted) {
        Map<Integer, List<Integer>> tree = new HashMap<>();
        Set<Integer> blockedNodes = new HashSet<>(Arrays.asList(restricted));

        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            tree.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            tree.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        int maxNodes = 0;

        // Using a stack to simulate the DFS traversal
        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int node = stack.pop();
            if (blockedNodes.contains(node)) {
                continue;
            }
            maxNodes = Math.max(maxNodes, tree.get(node).size());
            for (int child : tree.get(node)) {
                if (!blockedNodes.contains(child)) {
                    stack.push(child);
                }
            }
        }

        return maxNodes;
    }

