    public static int kSum(int[] nums, int k) {
        List<Integer> sums = new ArrayList<>();
        sums.add(0);

        for (int num : nums) {
            if (num > 0) {
                List<Integer> newSums = new ArrayList<>();
                for (int sum : sums) {
