    }

    private static int dfs(int node, int parent, int[] nums, Map<Integer, List<Integer>> graph, int total, List<Integer> result) {
        int totalSum = nums[node];
        for (int neighbor : graph.get(node)) {
            if (neighbor != parent) {
                totalSum += dfs(neighbor, node, nums, graph, total, result);
            }
        }
        if (totalSum == total / 2) {
            result.add(1);
            return 0;
        }
        return totalSum;
    }

