int countPartitions(std::vector<int>& nums, int k) {
    long long total_sum = 0;
    int n = nums.size();
    int mod = 1000000007;

    for (int num : nums) {
        total_sum += num;
    }

    if (total_sum < k * 2) {
        return 0;
