import java.util.PriorityQueue;
import java.util.Queue;

public class Solution {
    public static int getLastMoment(int n, int k, int[][] time) {
        Queue<int[]> left = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        Queue<int[]> right = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int i = 0; i < k; i++) {
            left.add(new int[]{time[i][0] + time[i][2], i});
        }

        while (n > 0) {
            while (!right.isEmpty() && right.peek()[0] <= left.peek()[0]) {
                int[] rightTop = right.poll();
                left.add(new int[]{rightTop[0] + time[rightTop[1]][0] + time[rightTop[1]][2], rightTop[1]});
            }
            int[] leftTop = left.poll();
            time[leftTop[1]][2] += time[leftTop[1]][3] + time[leftTop[1]][0] + time[leftTop[1]][1];
            right.add(new int[]{leftTop[0] + time[leftTop[1]][1], leftTop[1]});
            n--;
        }

        int lastMoment = 0;
        while (!right.isEmpty()) {
            lastMoment = Math.max(lastMoment, time[right.peek()[1]][2]);
            right.poll();
        }
        return lastMoment;
    }

    public static void main(String[] args) {
        int[][] time = {{1, 1, 2, 1}, {1, 1, 3, 1}, {1, 1, 4, 1}};
        System.out.println(getLastMoment(1, 3, time)); // Output: 6
    }
}
