        int n = nums.length;
        int[] cnt = new int[1001];
        for (int num : nums) {
            cnt[num]++;
        }

        int[][] dp = new int[n + 1][1001];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            int num = nums[i - 1];
            for (int j = 1000; j >= 0; j--) {
                for (int k = 0; k <= j; k++) {
                    dp[i][j] += dp[i - 1][k];
                    dp[i][j] %= MOD;
                    if (j >= num && (j / num) % 2 == 1) {
                        dp[i][j] -= dp[i - 1][k] * ((1 << (j - num)) - 1) % MOD;
                        if (dp[i][j] < 0) {
                            dp[i][j] += MOD;
                        }
                    }
                }
            }
        }
        return dp[n][0];
    }
