int countBeautifulSubsets(std::vector<int>& nums, int k) {
    std::sort(nums.begin(), nums.end());
    int ans = 0;
    std::vector<int> dp(nums.size(), 1);
    for (int i = 0; i < nums.size(); ++i) {
        int l = 0, r = 0;
        for (int j = 0; j < i; ++j) {
            while (l < j && nums[j] - nums[l] >= k) {
                ++l;
            }
            while (r + 1 < j && nums[r + 1] - nums[j] < k) {
                ++r;
            }
            dp[j] -= l <= r ? dp[l - 1] : 0;
            dp[j] += j > 0 ? dp[j - 1] + 1 : 1;
            ans += dp[j];
        }
    }
    return ans;
}

int main() {
    std::vector<int> nums = {2, 4, 6};
    int k = 2;
    std::cout << countBeautifulSubsets(nums, k) << std::endl; // Output: 4
    return 0;
}
