      double acceleration_time = time_accelerating(w, v, a);
      double acceleration_distance = distance_travelled(w, acceleration_time, a);
      if (acceleration_distance >= l - d) {
        //Accelerating w-?
        time += time_distance(w, a, l - d);
      } else {
