std::string longestPalindromeSubseq(const std::string& s) {
    int n = s.length();
    std::vector<std::vector<int>> dp(n, std::vector<int>(n));

    // Build the DP table
    for (int i = 0; i < n; ++i) {
        dp[i][i] = 1;
    }
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i <= n - len; ++i) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = std::max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }

    // Reconstruct the longest palindromic subsequence
    std::string lps;
    int i = 0, j = n - 1;
    while (i <= j) {
        if (s[i] == s[j]) {
            lps += s[i];
            ++i;
            --j;
        } else if (dp[i + 1][j] >= dp[i][j - 1]) {
            ++i;
        } else {
            --j;
        }
    }

    return lps;
}

int main() {
    std::string s;
    std::cin >> s;

    std::string result = longestPalindromeSubseq(s);
    std::cout << reverseString(result) << std::endl;

    return 0;
}
