        }
        System.out.println(heist(n, a));
    }

    public static int heist(int n, int[] a) {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        for (int num : a) {
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }
        return max - min - n + 1;
    }
}
