	public void solve(InputReader in, PrintWriter out) {
		int n = in.nextInt();
		String s = in.next(), ss;
		String ans = s;
		StringBuilder sb;
		int delta;
		int i, j, k;

		for (i=0; i<n; ++i) {
			ss = s.substring(i, n) + s.substring(0, i);
